create table RB_ACCT_DOSS (INTERNAL_KEY INT not null  ,CLIENT_NO VARCHAR(22) not null  ,BASE_ACCT_NO VARCHAR(50) null  ,PROD_TYPE VARCHAR(20) null  ,ACCT_CCY VARCHAR(3) null  ,ACCT_SEQ_NO VARCHAR(5) null  ,ACCT_STATUS VARCHAR(1) null  ,ACCT_NAME VARCHAR(100) null  ,TRAN_DATE TIMESTAMP(3) null  ,TRAN_BRANCH VARCHAR(30) null  ,DOSS_OPERATE_TYPE VARCHAR(2) null  ,AMT_TYPE VARCHAR(10) null  ,BALANCE DECIMAL(17,2) null  ,DORMANT_DATE TIMESTAMP(3) null  ,DOSS_DATE TIMESTAMP(3) null  ,OUT_DATE TIMESTAMP(3) null  ,INT_AMT DECIMAL(17,2) null  ,POR_INT_TOT DECIMAL(17,2) null  ,TAX_SC DECIMAL(17,2) null  ,REMARK VARCHAR(200) null  ,USER_ID VARCHAR(30) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  , primary key(INTERNAL_KEY,CLIENT_NO));